_history_url_season_episode:
def _history_url_season_episode(source: dict) -> tuple[str, str] | None:
    # Many Ashdi/UAKino playlists expose ambiguous UI labels such as "1-22" while
    # the actual media path carries the canonical SxxEyy identity. Parse the URL
    # path only (never query parameters) to avoid accidental matches in signed URLs.
    try:
        path = urlparse(str(source.get('url') or '')).path
    except Exception:
        return None
    match = re.search(r'(?i)(?:^|[._/\-])s(\d{1,3})e(\d{1,3})(?:[._/\-]|$)', path)
    if not match:
        return None
    season, episode = int(match.group(1)), int(match.group(2))
    if not (0 < season <= 999 and 0 <= episode <= 9999):
        return None
    return str(season), str(episode)

_history_source_season:
def _history_source_season(job: dict, source: dict) -> str:
    if _history_media_type(job) == 'movie':
        return ''
    url_identity = _history_url_season_episode(source)
    if url_identity:
        return url_identity[0]
    explicit = str(source.get('season') or '').strip()
    if explicit.isdigit() and 0 < int(explicit) <= 999:
        return str(int(explicit))
    for value in (
        source.get('discovery_page_title'), source.get('history_page_url'), source.get('discovery_page_url'),
        source.get('page_title'), job.get('season'), job.get('title'), job.get('page_url'),
    ):
        number = _season_number_from_text(value)
        if number is not None:
            return str(number)
    return str(source.get('season') or job.get('season') or '1')

_history_source_episode:
def _history_source_episode(job: dict, source: dict) -> str:
    if _history_media_type(job) == 'movie':
        return ''
    url_identity = _history_url_season_episode(source)
    if url_identity:
        return 'Пілот / спецсерія' if int(url_identity[1]) == 0 else f'Серія {int(url_identity[1])}'
    raw = ' '.join(str(source.get('episode') or '').split())
    if not raw:
        return ''
    if raw.isdigit():
        return 'Пілот / спецсерія' if int(raw) == 0 else f'Серія {int(raw)}'
    match = re.fullmatch(r'(?i)(?:сер(?:ія|ия)|episode)\s*(\d+)', raw)
    if match:
        return 'Пілот / спецсерія' if int(match.group(1)) == 0 else f'Серія {int(match.group(1))}'
    return raw
